(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const all=[...(window.OPERATORS||[]),...(window.NPC_INDEX||[]),...(window.SUPPORT_UNITS||[])];
 const index=new Map(all.map(x=>[x.id,x]));
 const D=window.TERRA;
 const B=window.BIOGRAPHY_UI;
 D.sources.push({id:'game-data',title:'中文游戏数据公开镜像 · 本次版本',type:'社区维护的游戏数据转录，不是鹰角运营站点',url:'https://github.com/Kengxxiao/ArknightsGameData/tree/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel',note:'完整干员名录、各阶段档案、晋升记录、干员密录正文及异格关联据此核对。网页发布原创人物纪事、关系说明与少量元数据，不提供完整解包档案。快照筛选口径与文件摘要见页面下方版本记录。'});
 const kinds={operator:'干员人物纪事',npc:'主要剧情人物',support:'特殊支援单位'};
 const regional=id=>D.regions.find(r=>r.id===id)||{name:'跨地区与来访者',color:'#837157',glyph:'◇',en:'TRAVELLERS'};
 let state={kind:'operator',page:1,signature:'',filters:null,prefs:null};
 let hooks={};
 const aliasName={'阿米娅':'阿米娅','幼年的阿米娅':'阿米娅','玛嘉烈·临光':'临光','玛莉娅·临光':'瑕光','祖玛玛／森蚺':'森蚺','流明／乔迪':'流明','异客／艾利奥特':'异客','初雪／恩雅':'初雪','崖心／恩希亚':'崖心'};
 function byName(name){name=aliasName[name]||name;return all.find(x=>x.name===name||x.aliases?.includes(name));}
 function matching(q,x){return [x.name,x.en,x.title,x.summary,B.textOf(x),window.PROFILE_UI?.textOf(x),x.role,x.origin,x.faction,(x.aliases||[]).join(' '),regional(x.region).name].join(' ').toLowerCase().includes(q.toLowerCase());}
 function pageHeading(){return `<div class="page-heading"><div><div class="eyebrow">ALL OPERATORS & KEY CHARACTERS</div><h1>干员与主要剧情人物</h1><p>按时间顺序阅读主要经历、关键事件和人物关系。同一人的异格经历合并为一篇纪事，原有形态入口全部保留；未明确的年份和分支单独说明。</p></div><div class="page-mark" aria-hidden="true">人</div></div>`;}
 function people(filters,prefs){return `<div class="wrap">${pageHeading()}<div class="roster-counts"><div><strong>${window.ROSTER_META.operatorCount}</strong><span>常规干员条目 · 含异格</span></div><div><strong>${window.ROSTER_META.npcCount}</strong><span>主要剧情人物选录</span></div><div><strong>${window.ROSTER_META.supportCount}</strong><span>特殊支援单位条目</span></div></div><div class="toolbar"><label class="search-inline"><input id="filter-query" type="search" value="${esc(filters.q)}" placeholder="搜索姓名、代号、出身地或经历…" aria-label="筛选人物"></label><select id="filter-region" aria-label="按关联地区筛选"><option value="all">全部关联地区</option>${D.regions.map(r=>`<option value="${r.id}" ${filters.region===r.id?'selected':''}>${r.name}</option>`).join('')}<option value="other" ${filters.region==='other'?'selected':''}>跨地区与来访者</option></select><span class="result-count" id="result-count"></span></div><div class="filter-chips" role="group" aria-label="人物资料类型">${Object.keys(kinds).map(kind=>`<button class="chip ${state.kind===kind?'active':''}" data-roster-kind="${kind}" aria-pressed="${state.kind===kind}">${kind==='operator'?'全部干员':kinds[kind]}</button>`).join('')}</div><div class="low-spoiler-banner"><span>${prefs.full?'完整阅读已开启。人物纪事包含后期事件、关系变化和关键结局。':'低剧透导览：先看姓名与资料类型，开启完整阅读后显示经历。'}</span><button data-action="toggle-full">${prefs.full?'切换低剧透':'开启完整阅读'}</button></div><p class="index-boundary">${esc(window.ROSTER_META.scope)} <a href="#/sources">版本与资料说明 ↗</a></p><div class="people-grid" id="people-results"></div><nav class="roster-pagination" id="roster-pagination" aria-label="人物目录分页"></nav></div>`;}
 function draw(filters,prefs){state.filters=filters;state.prefs=prefs;const signature=JSON.stringify([filters.q,filters.region,state.kind]);if(signature!==state.signature){state.page=1;state.signature=signature;}const list=all.filter(x=>x.kind===state.kind&&(filters.region==='all'||x.region===filters.region)&&(!filters.q||matching(filters.q,x)));const pages=Math.max(1,Math.ceil(list.length/60));state.page=Math.min(state.page,pages);const shown=list.slice((state.page-1)*60,state.page*60);document.getElementById('result-count').textContent=`${list.length} 条 · 第 ${state.page} / ${pages} 页`;document.getElementById('people-results').innerHTML=shown.length?shown.map(p=>{const r=regional(p.region);return `<a class="person-card" href="#/character/${p.id}" style="--r:${r.color}">${window.ART_UI.thumb(p)}<div class="meta">${kinds[p.kind]}</div><h3>${esc(p.name)}</h3><p>${prefs.full?esc(p.title||p.role):esc(p.faction||r.name)}</p><span class="meta">${esc(r.name)} <span aria-hidden="true">↗</span></span></a>`;}).join(''):'<div class="empty"><h2>还没有找到这个名字</h2><p>试试常用代号、其他资料类型，或取消地区筛选。</p><button data-action="reset-filters">重置筛选</button></div>';document.getElementById('roster-pagination').innerHTML=`<button data-roster-page="${state.page-1}" ${state.page<=1?'disabled':''}>← 上一页</button><span>${state.page} / ${pages} · 每页最多 60 条</span><button data-roster-page="${state.page+1}" ${state.page>=pages?'disabled':''}>下一页 →</button>`;document.querySelectorAll('[data-roster-kind]').forEach(b=>{b.classList.toggle('active',b.dataset.rosterKind===state.kind);b.setAttribute('aria-pressed',b.dataset.rosterKind===state.kind);});}
 function recordPage(id,prefs){const p=index.get(id);if(!p)return null;const r=regional(p.region);const bio=B.get(p.id);const formIds=(p.forms||[]).filter(x=>!x.patch&&x.id!==p.id);const curated=D.stories.filter(s=>s.people.some(x=>byName(x[0])?.id===p.id)||(p.groups||[]).some(g=>s.groups.includes(g)));const sources=(p.groups||[]).map(g=>window.CHAPTER_INDEX?.[g]).filter(Boolean);return `<div class="book-top"><div class="crumb"><a href="#/people">人物纪事</a><span>/</span><span>${kinds[p.kind]}</span><span>/</span><span>${esc(p.name)}</span></div><div class="reading-tools"><button data-action="toggle-full" class="${prefs.full?'selected':''}" aria-pressed="${prefs.full}">${prefs.full?'完整阅读 · 含剧透':'低剧透导览'}</button><button data-action="smaller" aria-label="减小正文字号" ${prefs.size<=16?'disabled':''}>A−</button><button data-action="larger" aria-label="增大正文字号" ${prefs.size>=24?'disabled':''}>A＋</button></div></div><div class="record-layout ${bio&&prefs.full?'with-biography':''}">${bio&&prefs.full?B.toc(p):''}<article class="book"><header class="book-head"><div class="eyebrow">${esc(r.en)} · ${kinds[p.kind]}</div><h1>${esc(p.name)}</h1><div class="book-subtitle">${bio?'分阶段经历 · 关键事件 · 人物关系':esc(p.title||p.role||'档案中的一个名字')}</div><div class="book-meta"><span>${esc(p.en||'TERRA')}</span><span>原创改写与解读</span><span>${esc(r.name)}</span></div></header><div class="character-art-block">${window.ART_UI.render(p)}</div>${window.PROFILE_UI?.get(p.id)?window.PROFILE_UI.render(p,prefs.full):`<dl class="record-facts"><div><dt>出身地</dt><dd>${esc(p.origin||'未在本条确认')}</dd></div><div><dt>档案关系</dt><dd>${esc(p.faction||'剧情人物')}</dd></div>${p.profession?`<div><dt>游戏职业</dt><dd>${esc(p.profession)}</dd></div>`:''}</dl>`}<p class="index-boundary">关联地区用于主题检索，不等同于国籍或出身地。正文区分明确先后、时间未定及分支叙事，不用材料解锁顺序代替人生顺序。</p>${prefs.full?B.render(p,byName):`<div class="spoiler-gate"><div class="eyebrow">BEFORE YOU CONTINUE</div><h2>阅读主要经历与关系变化</h2><p>人物纪事按可确认的阶段整理，包含关键事件、身份变化及结局。部分记忆、分支和未定时间会单独标明。</p><button class="primary" data-roster-enable="true">开启完整阅读 →</button></div>`}${formIds.length||p.forms?.some(x=>x.patch)?`<section class="record-related"><h2>同一人物的其他阶段</h2><div class="route-steps">${formIds.map(f=>`<a href="#/character/${f.id}">${esc(f.name)} ↗</a>`).join('')}${p.forms.filter(x=>x.patch).map(f=>`<span class="form-tag">${esc(f.name)} · 同条目升变</span>`).join('')}</div><p class="index-boundary">按游戏正式异格关联表建立联系，单条经历以该形态档案为准。</p></section>`:''}${p.memories?.length?`<section class="record-related"><h2>可以继续读的干员密录</h2><div class="memory-list">${p.memories.map(m=>`<a href="${p.source}" target="_blank" rel="noopener noreferrer">《${esc(m.title)}》 <span>前往档案页查找 ↗</span></a>`).join('')}</div></section>`:''}${window.REGION_UI.backlinks(p,prefs.full)}<section class="source-details"><h2 style="font-size:20px">本条出处与覆盖范围</h2><p>${p.kind==='operator'?'以同一人物各关联形态的公开档案、晋升记录和已读取的干员密录正文为主要材料，并结合已列出处的主线及活动记录。各阶段附材料说明；未逐章核实的内容不补写。':p.kind==='support'?'特殊行动单位单独列出；部分单位没有充分个人档案，匿名或重复单位不作为不同自然人计数。':'根据所列剧情时点建立主要 NPC 入口。主题归属不是完整生平，部分称谓代表群体或职位。'}</p><p><a href="${p.source}" target="_blank" rel="noopener noreferrer">${esc(p.name)} · PRTS 资料入口 ↗</a>（玩家维护，含官方文本转录与玩家整理，请区分阅读。）</p>${sources.length?`<p>剧情定位：${sources.map(s=>esc(s.title)).join('；')}。可在 <a href="https://terra-library.pages.dev/" target="_blank" rel="noopener noreferrer">泰拉文库</a> 按篇名查找。</p>`:''}<p>名录与形态快照：${window.ROSTER_META.date}。<a href="#/sources">查看数据版本与编写说明 ↗</a></p></section><nav class="next-chapters"><a href="#/people"><small>← 返回索引</small><strong>继续认识大地上的人</strong></a><a href="#/atlas/${p.region==='other'?'':p.region}"><small>走进地区 →</small><strong>${esc(r.name)}</strong></a></nav></article></div>`;}
 function search(q,prefs){const items=all.filter(x=>matching(q,x)).slice(0,24);return items.length?`<div class="eyebrow" style="margin:23px 0 12px">人物与档案 · 最多显示 24 条</div>${items.map(p=>`<a class="search-result" href="#/character/${p.id}" data-close-dialog="search-dialog"><small>${kinds[p.kind]} / ${regional(p.region).name}</small><h3>${esc(p.name)}</h3><p>${esc(prefs.full?p.title:p.faction)}</p></a>`).join('')}`:'';}
 document.addEventListener('click',e=>{const kind=e.target.closest('[data-roster-kind]');if(kind){state.kind=kind.dataset.rosterKind;draw(state.filters,state.prefs);}const page=e.target.closest('[data-roster-page]');if(page&&!page.disabled){state.page=Number(page.dataset.rosterPage);draw(state.filters,state.prefs);document.querySelector('.toolbar')?.scrollIntoView({block:'start'});}if(e.target.closest('[data-roster-enable]'))hooks.enableFull?.();});
 window.ROSTER_RENDER={people,draw,recordPage,search,byName,all,index,configure:h=>hooks=h};
})();
